import { type Clock, type EventBus, newId, systemClock } from "../kernel";
import type { Consent, ConsentChanged, ConsentChannel, ConsentRepository } from "./consent";
import type { Person, PersonRegistered, PersonRepository } from "./person";

export interface RegisterPersonInput {
  email: string;
  givenName: string;
  familyName: string;
  brand?: string;
}

export interface RecordConsentInput {
  personId: string;
  purpose: string;
  textVersion: string;
  channel: ConsentChannel;
  granted: boolean;
}

export class EmailAlreadyRegisteredError extends Error {
  constructor() {
    super("A person with this e-mail exists");
    this.name = "EmailAlreadyRegisteredError";
  }
}

export class PersonNotFoundError extends Error {
  constructor() {
    super("No person with this ID");
    this.name = "PersonNotFoundError";
  }
}

export interface IdentityDeps {
  repo: PersonRepository;
  consents: ConsentRepository;
  bus: EventBus;
  clock?: Clock;
}

function required(value: string, field: string): string {
  const trimmed = value.trim();
  if (!trimmed) throw new Error(`A consent needs a ${field}`);
  return trimmed;
}

/** Oldest first. A stable sort keeps the insertion order of decisions in the same millisecond. */
function byDecidedAt(records: Consent[]): Consent[] {
  return [...records].sort((a, b) => a.decidedAt.localeCompare(b.decidedAt));
}

export function createIdentity({ repo, consents, bus, clock = systemClock }: IdentityDeps) {
  return {
    /** One person record per e-mail address (T3-D-009). */
    async registerPerson(input: RegisterPersonInput): Promise<Person> {
      const email = input.email.trim().toLowerCase();
      if (await repo.findByEmail(email)) throw new EmailAlreadyRegisteredError();
      const now = clock.now();
      const person: Person = {
        id: newId(now),
        email,
        givenName: input.givenName,
        familyName: input.familyName,
        erpCustomerNumber: null,
        brand: input.brand ?? "provital",
        createdAt: now.toISOString(),
      };
      await repo.insert(person);
      const event: PersonRegistered = {
        type: "identity.person-registered",
        id: newId(now),
        occurredAt: now.toISOString(),
        payload: { personId: person.id, brand: person.brand },
      };
      await bus.publish(event);
      return person;
    },

    async getPerson(id: string): Promise<Person | null> {
      return repo.findById(id);
    },

    /** Appends a consent record; a withdrawal is a record with `granted: false` (T3-AC-004). */
    async recordConsent(input: RecordConsentInput): Promise<Consent> {
      const purpose = required(input.purpose, "purpose");
      const textVersion = required(input.textVersion, "text version");
      if (!(await repo.findById(input.personId))) throw new PersonNotFoundError();
      const now = clock.now();
      const consent: Consent = {
        id: newId(now),
        personId: input.personId,
        purpose,
        textVersion,
        channel: input.channel,
        granted: input.granted,
        decidedAt: now.toISOString(),
      };
      await consents.insert(consent);
      const event: ConsentChanged = {
        type: "identity.consent-changed",
        id: newId(now),
        occurredAt: consent.decidedAt,
        payload: { consentId: consent.id, personId: consent.personId },
      };
      await bus.publish(event);
      return consent;
    },

    /** The latest record of the person for the purpose, or `null`. */
    async currentConsent(personId: string, purpose: string): Promise<Consent | null> {
      const history = byDecidedAt(await consents.listByPerson(personId));
      return history.filter((consent) => consent.purpose === purpose.trim()).at(-1) ?? null;
    },

    /** All records of the person, oldest first. */
    async consentHistory(personId: string): Promise<Consent[]> {
      return byDecidedAt(await consents.listByPerson(personId));
    },
  };
}

export type Identity = ReturnType<typeof createIdentity>;

