        id: newId(now),
        occurredAt: consent.decidedAt,
        payload: { consentId: consent.id, personId: consent.personId },
      };
      await bus.publish(event);
      return consent;
    },

    /** The latest record of the person for the purpose, or `null`. */
    async currentConsent(personId: string, purpose: string): Promise<Consent | null> {
      const history = byDecidedAt(await consents.listByPerson(personId));
      return history.filter((consent) => consent.purpose === purpose.trim()).at(-1) ?? null;
    },

    /** All records of the person, oldest first. */
    async consentHistory(personId: string): Promise<Consent[]> {
      return byDecidedAt(await consents.listByPerson(personId));
    },
  };
}

export type Identity = ReturnType<typeof createIdentity>;

