import { describe, expect, it } from "vitest";
import { fixedClock, InMemoryEventBus } from "../kernel";
import { createIdentity, EmailAlreadyRegisteredError, InMemoryPersonRepository } from "./index";

function setup() {
  const bus = new InMemoryEventBus();
  const identity = createIdentity({
    repo: new InMemoryPersonRepository(),
    bus,
    clock: fixedClock("2027-01-05T08:00:00Z"),
  });
  return { bus, identity };
}

describe("identity", () => {
  it("T3-AC-003: keeps one person record per e-mail address", async () => {
    const { identity } = setup();
    await identity.registerPerson({
      email: "Erika@Example.test",
      givenName: "Erika",
      familyName: "Muster",
    });
    await expect(
      identity.registerPerson({ email: "erika@example.test", givenName: "E", familyName: "M" }),
    ).rejects.toBeInstanceOf(EmailAlreadyRegisteredError);
  });

  it("publishes identity.person-registered", async () => {
    const { bus, identity } = setup();
    const person = await identity.registerPerson({
      email: "max@example.test",
      givenName: "Max",
      familyName: "Beispiel",
    });
    expect(bus.published).toHaveLength(1);
    expect(bus.published[0]).toMatchObject({
      type: "identity.person-registered",
      payload: { personId: person.id },
    });
  });
});

import { identity, integration, journey, kernel } from "@provital/core";
import { createFakeErp, type FakeErpOptions } from "@provital/erp-fake";

export interface AppOptions {
  clock?: kernel.Clock;
  erp?: FakeErpOptions;
}

/**
 * The composition root. The worker is one of two runtime units that load an ERP adapter
 * (architecture rule 2). In this fixture it wires the fake adapter.
 */
export function createApp(options: AppOptions = {}) {
  const clock = options.clock ?? kernel.systemClock;
  const bus = new kernel.InMemoryEventBus();
  const erp = createFakeErp(options.erp);
  const integrationApi = integration.createIntegration({ erp, clock });
  const identityApi = identity.createIdentity({
    repo: new identity.InMemoryPersonRepository(),
    bus,
    clock,
  });
  const journeyApi = journey.createJourney({
    repo: new journey.InMemoryTaskRepository(),
    bus,
    clock,
  });
  return { bus, clock, integration: integrationApi, identity: identityApi, journey: journeyApi };
}

export type App = ReturnType<typeof createApp>;

